"use strict";(self.webpackChunkpf_1_ee=self.webpackChunkpf_1_ee||[]).push([[4347],{3479:(e,a,n)=>{n.r(a),n.d(a,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>r,metadata:()=>t,toc:()=>h});const t=JSON.parse('{"id":"srd/races/versatile-lineages/half-human","title":"Half-Human","description":"Half-Humans are the children of two worlds, born from the union of a human and another mortal ancestry\u2014elves, orcs, dwarves, gnomes, and others of the Material Plane. Sometimes welcomed, often distrusted, these individuals stand as living proof that the boundaries between peoples can be crossed\u2014whether by love, desperation, or accident.","source":"@site/docs/srd/races/versatile-lineages/half-human.md","sourceDirName":"srd/races/versatile-lineages","slug":"/srd/races/versatile-lineages/half-human","permalink":"/PF1EE/docs/srd/races/versatile-lineages/half-human","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/srd/races/versatile-lineages/half-human.md","tags":[],"version":"current","frontMatter":{},"sidebar":"srdSidebar","previous":{"title":"Dhampirs","permalink":"/PF1EE/docs/srd/races/versatile-lineages/dhampirs"},"next":{"title":"Skinwalkers","permalink":"/PF1EE/docs/srd/races/versatile-lineages/skinwalkers"}}');var s=n(4848),i=n(8453);const r={},o="Half-Human",l={},h=[{value:"Half-Human Details",id:"half-human-details",level:2},{value:"Half-Human Lineages",id:"half-human-lineages",level:2},{value:"Versatile-Blooded Lineage",id:"versatile-blooded-lineage",level:3}];function d(e){const a={em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"half-human",children:"Half-Human"})}),"\n",(0,s.jsx)(a.p,{children:"Half-Humans are the children of two worlds, born from the union of a human and another mortal ancestry\u2014elves, orcs, dwarves, gnomes, and others of the Material Plane. Sometimes welcomed, often distrusted, these individuals stand as living proof that the boundaries between peoples can be crossed\u2014whether by love, desperation, or accident."}),"\n",(0,s.jsx)(a.p,{children:"No two Half-Humans are alike. They may inherit their non-human parent's pointed ears, tusks, rugged stature, or vivid coloring\u2014but always tempered by human eyes, expressions, or resilience. Some are born into two worlds, others into none. In cities, they might be viewed with wary curiosity; in isolated settlements, with suspicion or outright hostility. Much depends on the nature of their parentage\u2014and how well humanity tolerates the blood of \u201cothers.\u201d"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Inheritance and Identity:"})," Half-Humans often grow up grappling with the question of belonging. Some lean toward one side of their heritage, shaped by culture, kinship, or survival. Others reject both, carving out new paths or redefining what it means to be one\u2019s own person. The flexibility and passion of human blood burns within them, granting an adaptability few others can match."]}),"\n",(0,s.jsx)(a.p,{children:"While many Half-Humans are shaped by hardship, they also thrive in the in-between. They make natural diplomats, interpreters, mercenaries, and wanderers\u2014people who speak many tongues, know many faces, and learn to read the room before it reads them."}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"The Human Spark:"})," Among the myriad peoples of the world, humanity is uniquely mutable. Half-Humans often manifest traits that wouldn\u2019t normally appear among their non-human parent\u2019s kin. Some gain strange magical talents or uncanny charm; others inherit a tenacity that defies their physical form. This spark makes Half-Humans more than a sum of parts\u2014it makes them potential."]}),"\n",(0,s.jsx)(a.p,{children:"Whether born in noble halls or battlefield camps, Half-Humans stand at the edge of two legacies. What they become is entirely their own."}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Versatile by Blood:"})," The defining trait of Half-Humans is their inherited diversity. From their human lineage they gain creativity, ambition, and flexibility. From their non-human parent, they inherit power\u2014be it grace, strength, endurance, or wit. Some resemble their non-human kin almost entirely; others pass for humans with only subtle hints of their origins."]}),"\n",(0,s.jsx)(a.p,{children:"Half-Humans may be born to elves, dwarves, orcs, halflings, gnomes, or other humanoid races."}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"half-human-details",children:"Half-Human Details"}),"\n",(0,s.jsx)(a.p,{children:"To play a character with a Half-Human lineage, first select your race, just like you would for any character. You gain hit points, type, size, speed, languages, racial traits, and other abilities from that race. Then, instead of choosing a lineage from those normally available to that race, apply your chosen Half-Human lineage. You gain all the features from your Half-Human lineage, some of which might modify or replace statistics, abilities, or traits from your race."}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"When you apply a Half-Human lineage, you gain the Half-Human subtype,"})," while retaining any racial subtypes, creature size, and racial traits associated with your base race (e.g., Dwarf, Elf, Orc)."]}),"\n",(0,s.jsx)(a.p,{children:"Since a Half-Human lineage is a lineage, you can only apply one, and you cannot take another lineage in addition to your Half-Human lineage."}),"\n",(0,s.jsx)(a.p,{children:"When selecting racial traits, you can choose from those available to your race as well as those available to your Half-Human lineage."}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"half-human-lineages",children:"Half-Human Lineages"}),"\n",(0,s.jsx)(a.h3,{id:"versatile-blooded-lineage",children:"Versatile-Blooded Lineage"}),"\n",(0,s.jsx)(a.p,{children:"Those of the Versatile-Blooded lineage are born from the union of humanity and another common humanoid ancestry\u2014such as elf, dwarf, gnome, halfling, or orc. Though they inherit traits from both parents, it is the human adaptability within them that shines most strongly, granting them a flexibility that defies rigid expectations. Versatile-Blooded individuals often thrive in diverse roles, finding success in both martial and magical paths with equal ease."}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Adaptability:"})," Versatile-Blooded characters gain the ",(0,s.jsx)(a.em,{children:"Skill Focus"})," feat as a bonus feat at 1st level."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Versatile Training:"})," At 1st level, a Versatile-Blooded character selects any two skills. These skills are always considered class skills for them."]}),"\n"]}),"\n",(0,s.jsxs)(a.li,{children:["\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Natural Linguist:"})," Versatile-Blooded characters with high Intelligence scores can select any language (except secret languages such as Druidic) as bonus languages, regardless of their race."]}),"\n"]}),"\n"]})]})}function c(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},8453:(e,a,n)=>{n.d(a,{R:()=>r,x:()=>o});var t=n(6540);const s={},i=t.createContext(s);function r(e){const a=t.useContext(i);return t.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function o(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),t.createElement(i.Provider,{value:a},e.children)}}}]);